/** Database overrides take precedence over environment-bound configuration. */
@Service
public class RuntimeProviderSettings {
  private final ProviderSettingsRepository repository; private final ContextCrateProperties properties;private final RagSettingsRepository rag;private final SharedModelRepository shared;private final SystemSettingRepository system;
  public RuntimeProviderSettings(ProviderSettingsRepository repository,ContextCrateProperties properties){this(repository,properties,null,null,null);}
  @org.springframework.beans.factory.annotation.Autowired public RuntimeProviderSettings(ProviderSettingsRepository repository,ContextCrateProperties properties,RagSettingsRepository rag,SharedModelRepository shared,SystemSettingRepository system){this.repository=repository;this.properties=properties;this.rag=rag;this.shared=shared;this.system=system;}
  @Transactional(readOnly = true) public ProviderSettings current(){return current(CrateContext.current());}
  @Transactional(readOnly = true) public ProviderSettings current(java.util.UUID crateId){return repository.findById(crateId).orElseThrow(()->new IllegalStateException("Provider settings are not initialized for crate "+crateId));}
  @Transactional public void update(ProviderForm f){update(CrateContext.current(),f);}
  @Transactional public void update(java.util.UUID crateId,ProviderForm f){if(!"local".equals(f.embeddingProvider())&& !"openai-compatible".equals(f.embeddingProvider()))throw new IllegalArgumentException("embedding provider must be local or openai-compatible");if(!"local".equals(f.rerankingProvider())&& !"cohere-compatible".equals(f.rerankingProvider()))throw new IllegalArgumentException("reranking provider must be local or cohere-compatible");if(f.embeddingDimensions()<1)throw new IllegalArgumentException("embedding dimensions must be positive");if(f.embeddingMaxInputCharacters()<256)throw new IllegalArgumentException("maximum embedding input characters must be at least 256");if(f.rerankingCandidateLimit()<1||f.rerankingCandidateLimit()>100)throw new IllegalArgumentException("reranking candidate limit must be between 1 and 100");if(f.rerankingMaxInputCharacters()<256)throw new IllegalArgumentException("maximum reranking input characters must be at least 256");if(f.rerankingTimeoutSeconds()<5)throw new IllegalArgumentException("reranking timeout must be at least 5 seconds");var s=current(crateId);var se=selectShared(f.embeddingSharedModelId(),SharedModel.Kind.EMBEDDING,s.getEmbeddingSharedModelId());var sr=selectShared(f.rerankingSharedModelId(),SharedModel.Kind.RERANKING,s.getRerankingSharedModelId());var sa=selectShared(f.answeringSharedModelId(),SharedModel.Kind.ANSWER,s.getAnsweringSharedModelId());boolean eShared=se!=null,rShared=sr!=null,aShared=sa!=null;enforcePolicy(crateId,f,eShared,rShared,aShared);s.selectSharedModels(se,sr,sa);boolean changed=!eShared&&(!java.util.Objects.equals(s.getEmbeddingOpenaiBaseUrl(),blank(f.embeddingBaseUrl()))||!java.util.Objects.equals(s.getEmbeddingOpenaiModel(),blank(f.embeddingRemoteModel())));s.update(f.embeddingsEnabled(),f.embeddingProvider(),blank(f.embeddingModelId()),blank(f.embeddingRevision()),blank(f.embeddingDownloadUrl()),blank(f.embeddingCachePath()),blank(f.embeddingModelPath()),eShared?s.getEmbeddingOpenaiBaseUrl():blank(f.embeddingBaseUrl()),eShared?s.getEmbeddingOpenaiModel():blank(f.embeddingRemoteModel()),eShared?null:f.embeddingApiKey(),eShared?s.getEmbeddingOpenaiDimensions():Integer.valueOf(f.embeddingDimensions()),eShared?s.getEmbeddingOpenaiMaxInputCharacters():Integer.valueOf(f.embeddingMaxInputCharacters()),f.rerankingEnabled(),f.rerankingProvider(),f.rerankingCandidateLimit(),blank(f.rerankingModelId()),blank(f.rerankingRevision()),blank(f.rerankingDownloadUrl()),blank(f.rerankingCachePath()),blank(f.rerankingModelPath()),rShared?s.getRerankingCohereBaseUrl():blank(f.rerankingBaseUrl()),rShared?s.getRerankingCohereModel():blank(f.rerankingRemoteModel()),rShared?null:f.rerankingApiKey(),rShared?s.getRerankingCohereMaxInputCharacters():Integer.valueOf(f.rerankingMaxInputCharacters()),rShared?s.getRerankingCohereTimeoutSeconds():Integer.valueOf(f.rerankingTimeoutSeconds()),f.answeringEnabled(),aShared?s.getAnsweringBaseUrl():blank(f.answeringBaseUrl()),aShared?s.getAnsweringModel():blank(f.answeringModel()),aShared?null:f.answeringApiKey());s.setEmbeddingOpenaiAutomaticLimitRecovery(f.embeddingAutomaticLimitRecovery());if(changed)s.clearLearnedEmbeddingInputLimit();if(rag!=null&&rag.findById(crateId).map(x->"proposition".equals(x.getRetrievalStrategy())).orElse(false)){var e=effectiveEmbedding(crateId);var a=effectiveAnswer(crateId);boolean embeddingConfigured=e.enabled()&&("local".equals(e.provider())||e.openaiBaseUrl()!=null&&!e.openaiBaseUrl().isBlank()&&e.openaiModel()!=null&&!e.openaiModel().isBlank());if(!embeddingConfigured||!a.enabled()||a.baseUrl()==null||a.baseUrl().isBlank()||a.model()==null||a.model().isBlank())throw new IllegalArgumentException("Provider changes cannot disable requirements of proposition retrieval");}}
  public Embedding effectiveEmbedding(){var s=current();var e=properties.embeddings();var l=e.local();var o=e.openaiCompatible();var sm=sharedModel(s.getEmbeddingSharedModelId(),SharedModel.Kind.EMBEDDING);String base=sm!=null?sm.getBaseUrl():choose(s.getEmbeddingOpenaiBaseUrl(),o.baseUrl()),model=sm!=null?sm.getModel():choose(s.getEmbeddingOpenaiModel(),o.model());int configured=sm!=null&&sm.getMaxInputCharacters()!=null?sm.getMaxInputCharacters():s.getEmbeddingOpenaiMaxInputCharacters()==null?o.maxInputCharacters():s.getEmbeddingOpenaiMaxInputCharacters();boolean recovery=s.getEmbeddingOpenaiAutomaticLimitRecovery()==null?o.automaticLimitRecovery():s.getEmbeddingOpenaiAutomaticLimitRecovery();Integer learned=java.util.Objects.equals(base,s.getEmbeddingOpenaiLearnedLimitBaseUrl())&&java.util.Objects.equals(model,s.getEmbeddingOpenaiLearnedLimitModel())?s.getEmbeddingOpenaiLearnedMaxInputCharacters():null;return new Embedding(s.getEmbeddingsEnabled()==null?e.enabled():s.getEmbeddingsEnabled(),sm!=null?"openai-compatible":choose(s.getEmbeddingsProvider(),e.provider()),choose(s.getEmbeddingLocalModelId(),l.modelId()),choose(s.getEmbeddingLocalRevision(),l.revision()),choose(s.getEmbeddingLocalDownloadUrl(),l.downloadUrl()),path(s.getEmbeddingLocalCachePath(),l.cachePath()),pathNullable(s.getEmbeddingLocalModelPath(),l.modelPath()),base,model,sm!=null?sm.getApiKey():choose(s.getEmbeddingOpenaiApiKey(),o.apiKey()),sm!=null&&sm.getDimensions()!=null?sm.getDimensions():s.getEmbeddingOpenaiDimensions()==null?o.dimensions():s.getEmbeddingOpenaiDimensions(),configured,recovery,learned==null?configured:Math.min(configured,learned));}
  public Embedding effectiveEmbedding(java.util.UUID crateId){try(var ignored=CrateContext.use(crateId)){return effectiveEmbedding();}}
  public Reranking effectiveReranking(){var s=current();var r=properties.reranking();var l=r.local();var c=r.cohereCompatible();var sm=sharedModel(s.getRerankingSharedModelId(),SharedModel.Kind.RERANKING);return new Reranking(s.getRerankingEnabled()==null?r.enabled():s.getRerankingEnabled(),sm!=null?"cohere-compatible":choose(s.getRerankingProvider(),r.provider()),s.getRerankingCandidateLimit()==null?r.candidateLimit():s.getRerankingCandidateLimit(),choose(s.getRerankingLocalModelId(),l.modelId()),choose(s.getRerankingLocalRevision(),l.revision()),choose(s.getRerankingLocalDownloadUrl(),l.downloadUrl()),path(s.getRerankingLocalCachePath(),l.cachePath()),pathNullable(s.getRerankingLocalModelPath(),l.modelPath()),l.downloadTimeoutSeconds(),sm!=null?sm.getBaseUrl():choose(s.getRerankingCohereBaseUrl(),c.baseUrl()),sm!=null?sm.getModel():choose(s.getRerankingCohereModel(),c.model()),sm!=null?sm.getApiKey():choose(s.getRerankingCohereApiKey(),c.apiKey()),sm!=null&&sm.getMaxInputCharacters()!=null?sm.getMaxInputCharacters():s.getRerankingCohereMaxInputCharacters()==null?c.maxInputCharacters():s.getRerankingCohereMaxInputCharacters(),sm!=null&&sm.getTimeoutSeconds()!=null?sm.getTimeoutSeconds():s.getRerankingCohereTimeoutSeconds()==null?c.timeoutSeconds():s.getRerankingCohereTimeoutSeconds());}
  public Reranking effectiveReranking(java.util.UUID crateId){try(var ignored=CrateContext.use(crateId)){return effectiveReranking();}}
  public Answering effectiveAnswer(){var s=current();var a=properties.answering();var o=a.openaiCompatible();var sm=sharedModel(s.getAnsweringSharedModelId(),SharedModel.Kind.ANSWER);return new Answering(s.getAnsweringEnabled()==null?a.enabled():s.getAnsweringEnabled(),sm!=null?sm.getBaseUrl():choose(s.getAnsweringBaseUrl(),o.baseUrl()),sm!=null?sm.getModel():choose(s.getAnsweringModel(),o.model()),sm!=null?sm.getApiKey():choose(s.getAnsweringApiKey(),o.apiKey()),o.headers(),sm!=null&&sm.getTimeoutSeconds()!=null?sm.getTimeoutSeconds():o.timeoutSeconds(),a.temperature(),a.maxOutputTokens());}
  public Answering effectiveAnswer(java.util.UUID crateId){try(var ignored=CrateContext.use(crateId)){return effectiveAnswer();}}

  private SharedModel sharedModel(java.util.UUID id,SharedModel.Kind kind){return id==null||shared==null?null:shared.findById(id).filter(m->m.getKind()==kind).orElse(null);}
  private java.util.UUID selectShared(String raw,SharedModel.Kind kind,java.util.UUID alreadySelected){
    if(raw==null||raw.isBlank())return null;
    java.util.UUID id;try{id=java.util.UUID.fromString(raw.trim());}catch(IllegalArgumentException e){throw new IllegalArgumentException("Unknown shared model");}
    var model=shared==null?null:shared.findById(id).orElse(null);
    if(model==null||model.getKind()!=kind)throw new IllegalArgumentException("Unknown shared model");
    if(!model.isAvailableToUsers()&&!id.equals(alreadySelected))throw new IllegalArgumentException("Shared model \""+model.getName()+"\" is not available");
    return id;
  }
  /** Which administrator-managed models a crate uses; {@code null} means its own endpoint. */
  public Selection selection(java.util.UUID crateId){var s=current(crateId);return new Selection(s.getEmbeddingSharedModelId(),s.getRerankingSharedModelId(),s.getAnsweringSharedModelId());}
  /** Safe for users: shared endpoints, models and keys are blanked, so only the administrator-given name can be shown. */
  public Embedding displayEmbedding(java.util.UUID crateId){var e=effectiveEmbedding(crateId);return selection(crateId).embedding()==null?e:new Embedding(e.enabled(),e.provider(),e.localModelId(),e.localRevision(),e.localDownloadUrl(),e.localCachePath(),e.localModelPath(),null,null,null,e.openaiDimensions(),e.openaiMaxInputCharacters(),e.automaticLimitRecovery(),e.effectiveOpenaiMaxInputCharacters());}
  public Reranking displayReranking(java.util.UUID crateId){var r=effectiveReranking(crateId);return selection(crateId).reranking()==null?r:new Reranking(r.enabled(),r.provider(),r.candidateLimit(),r.localModelId(),r.localRevision(),r.localDownloadUrl(),r.localCachePath(),r.localModelPath(),r.localDownloadTimeoutSeconds(),null,null,null,r.cohereMaxInputCharacters(),r.cohereTimeoutSeconds());}
  public Answering displayAnswer(java.util.UUID crateId){var a=effectiveAnswer(crateId);return selection(crateId).answering()==null?a:new Answering(a.enabled(),null,null,null,null,a.timeoutSeconds(),a.temperature(),a.maxOutputTokens());}
  /** The model name to advertise to API clients: the shared name when one is selected, never the upstream model id. */
  public String publicAnswerModel(java.util.UUID crateId){var id=selection(crateId).answering();var m=sharedModel(id,SharedModel.Kind.ANSWER);return m!=null?m.getName():effectiveAnswer(crateId).model();}
  public record Selection(java.util.UUID embedding,java.util.UUID reranking,java.util.UUID answering){}

  /** Administrator policy: may crate owners use their own endpoints / change local model settings? Defaults to yes. */
  public boolean allowCustomEndpoints(){return system==null||system.findById(1).map(x->x.isAllowCustomEndpoints()).orElse(true);}
  public boolean allowLocalModels(){return system==null||system.findById(1).map(x->x.isAllowLocalModels()).orElse(true);}
  /** Existing configuration keeps working; only changes to it are refused. Compared with the effective values so unchanged form posts pass. */
  private void enforcePolicy(java.util.UUID crateId,ProviderForm f,boolean eShared,boolean rShared,boolean aShared){
    boolean custom=allowCustomEndpoints(),local=allowLocalModels();if(custom&&local)return;
    var e=effectiveEmbedding(crateId);var r=effectiveReranking(crateId);var a=effectiveAnswer(crateId);
    if(!custom){
      String message="Custom endpoints are disabled by the administrator; choose a shared model instead";
      if(!eShared&&"openai-compatible".equals(f.embeddingProvider())&&(!"openai-compatible".equals(e.provider())||differs(e.openaiBaseUrl(),f.embeddingBaseUrl())||differs(e.openaiModel(),f.embeddingRemoteModel())||hasText(f.embeddingApiKey())))throw new IllegalArgumentException(message);
      if(!rShared&&"cohere-compatible".equals(f.rerankingProvider())&&(!"cohere-compatible".equals(r.provider())||differs(r.cohereBaseUrl(),f.rerankingBaseUrl())||differs(r.cohereModel(),f.rerankingRemoteModel())||hasText(f.rerankingApiKey())))throw new IllegalArgumentException(message);
      if(!aShared&&(differs(a.baseUrl(),f.answeringBaseUrl())||differs(a.model(),f.answeringModel())||hasText(f.answeringApiKey())))throw new IllegalArgumentException(message);
    }
    if(!local){
      if(differs(e.localModelId(),f.embeddingModelId())||differs(e.localRevision(),f.embeddingRevision())||differs(e.localDownloadUrl(),f.embeddingDownloadUrl())||differs(String.valueOf(e.localCachePath()),f.embeddingCachePath())||differs(e.localModelPath()==null?null:e.localModelPath().toString(),f.embeddingModelPath())
        ||differs(r.localModelId(),f.rerankingModelId())||differs(r.localRevision(),f.rerankingRevision())||differs(r.localDownloadUrl(),f.rerankingDownloadUrl())||differs(String.valueOf(r.localCachePath()),f.rerankingCachePath())||differs(r.localModelPath()==null?null:r.localModelPath().toString(),f.rerankingModelPath()))
        throw new IllegalArgumentException("Changing local models is disabled by the administrator");
    }
  }
  private static boolean hasText(String v){return v!=null&&!v.isBlank();}
  private static boolean differs(String current,String submitted){return !(current==null||current.isBlank()?"":current.trim()).equals(submitted==null||submitted.isBlank()?"":submitted.trim());}
  private static String choose(String value,String fallback){return value==null||value.isBlank()?fallback:value;}private static Path path(String value,Path fallback){return value==null||value.isBlank()?fallback:Path.of(value);}private static Path pathNullable(String value,Path fallback){return value==null||value.isBlank()?fallback:Path.of(value);}private static String blank(String value){return value==null||value.isBlank()?null:value.trim();}
  @Transactional public void learnEmbeddingInputLimit(java.util.UUID crateId,int maximum,String baseUrl,String model){var s=current(crateId);s.learnEmbeddingInputLimit(maximum,baseUrl,model);}
  public record Embedding(boolean enabled,String provider,String localModelId,String localRevision,String localDownloadUrl,Path localCachePath,Path localModelPath,String openaiBaseUrl,String openaiModel,String openaiApiKey,int openaiDimensions,int openaiMaxInputCharacters,boolean automaticLimitRecovery,int effectiveOpenaiMaxInputCharacters){public Embedding(boolean enabled,String provider,String localModelId,String localRevision,String localDownloadUrl,Path localCachePath,Path localModelPath,String openaiBaseUrl,String openaiModel,String openaiApiKey,int openaiDimensions,int openaiMaxInputCharacters){this(enabled,provider,localModelId,localRevision,localDownloadUrl,localCachePath,localModelPath,openaiBaseUrl,openaiModel,openaiApiKey,openaiDimensions,openaiMaxInputCharacters,true,openaiMaxInputCharacters);}}
  public record Reranking(boolean enabled,String provider,int candidateLimit,String localModelId,String localRevision,String localDownloadUrl,Path localCachePath,Path localModelPath,int localDownloadTimeoutSeconds,String cohereBaseUrl,String cohereModel,String cohereApiKey,int cohereMaxInputCharacters,int cohereTimeoutSeconds){}
  public record Answering(boolean enabled,String baseUrl,String model,String apiKey,String headers,int timeoutSeconds,double temperature,int maxOutputTokens){}
  public record ProviderForm(boolean embeddingsEnabled,String embeddingProvider,String embeddingModelId,String embeddingRevision,String embeddingDownloadUrl,String embeddingCachePath,String embeddingModelPath,String embeddingBaseUrl,String embeddingRemoteModel,String embeddingApiKey,int embeddingDimensions,int embeddingMaxInputCharacters,boolean embeddingAutomaticLimitRecovery,boolean rerankingEnabled,String rerankingProvider,int rerankingCandidateLimit,String rerankingModelId,String rerankingRevision,String rerankingDownloadUrl,String rerankingCachePath,String rerankingModelPath,String rerankingBaseUrl,String rerankingRemoteModel,String rerankingApiKey,int rerankingMaxInputCharacters,int rerankingTimeoutSeconds,boolean answeringEnabled,String answeringBaseUrl,String answeringModel,String answeringApiKey,String embeddingSharedModelId,String rerankingSharedModelId,String answeringSharedModelId){public ProviderForm(boolean embeddingsEnabled,String embeddingProvider,String embeddingModelId,String embeddingRevision,String embeddingDownloadUrl,String embeddingCachePath,String embeddingModelPath,String embeddingBaseUrl,String embeddingRemoteModel,String embeddingApiKey,int embeddingDimensions,int embeddingMaxInputCharacters,boolean embeddingAutomaticLimitRecovery,boolean rerankingEnabled,String rerankingProvider,int rerankingCandidateLimit,String rerankingModelId,String rerankingRevision,String rerankingDownloadUrl,String rerankingCachePath,String rerankingModelPath,String rerankingBaseUrl,String rerankingRemoteModel,String rerankingApiKey,int rerankingMaxInputCharacters,int rerankingTimeoutSeconds,boolean answeringEnabled,String answeringBaseUrl,String answeringModel,String answeringApiKey){this(embeddingsEnabled,embeddingProvider,embeddingModelId,embeddingRevision,embeddingDownloadUrl,embeddingCachePath,embeddingModelPath,embeddingBaseUrl,embeddingRemoteModel,embeddingApiKey,embeddingDimensions,embeddingMaxInputCharacters,embeddingAutomaticLimitRecovery,rerankingEnabled,rerankingProvider,rerankingCandidateLimit,rerankingModelId,rerankingRevision,rerankingDownloadUrl,rerankingCachePath,rerankingModelPath,rerankingBaseUrl,rerankingRemoteModel,rerankingApiKey,rerankingMaxInputCharacters,rerankingTimeoutSeconds,answeringEnabled,answeringBaseUrl,answeringModel,answeringApiKey,null,null,null);}public ProviderForm(boolean embeddingsEnabled,String embeddingProvider,String embeddingModelId,String embeddingRevision,String embeddingDownloadUrl,String embeddingCachePath,String embeddingModelPath,String embeddingBaseUrl,String embeddingRemoteModel,String embeddingApiKey,int embeddingDimensions,int embeddingMaxInputCharacters,boolean rerankingEnabled,String rerankingProvider,int rerankingCandidateLimit,String rerankingModelId,String rerankingRevision,String rerankingDownloadUrl,String rerankingCachePath,String rerankingModelPath,String rerankingBaseUrl,String rerankingRemoteModel,String rerankingApiKey,int rerankingMaxInputCharacters,int rerankingTimeoutSeconds,boolean answeringEnabled,String answeringBaseUrl,String answeringModel,String answeringApiKey){this(embeddingsEnabled,embeddingProvider,embeddingModelId,embeddingRevision,embeddingDownloadUrl,embeddingCachePath,embeddingModelPath,embeddingBaseUrl,embeddingRemoteModel,embeddingApiKey,embeddingDimensions,embeddingMaxInputCharacters,true,rerankingEnabled,rerankingProvider,rerankingCandidateLimit,rerankingModelId,rerankingRevision,rerankingDownloadUrl,rerankingCachePath,rerankingModelPath,rerankingBaseUrl,rerankingRemoteModel,rerankingApiKey,rerankingMaxInputCharacters,rerankingTimeoutSeconds,answeringEnabled,answeringBaseUrl,answeringModel,answeringApiKey);}}
}
